DROP VIEW IF EXISTS crmls.view_paxson CASCADE;
CREATE OR REPLACE VIEW crmls.view_paxson AS
  SELECT
   41::integer as area_id,
   vl.*,
   neigh_places.label as __geo_neigh
  FROM
    (select * from crmls.view_property WHERE ST_Within(__geo_geom, ST_SetSRID(''::geometry,4326))) vl
    LEFT OUTER JOIN
      (
        SELECT * FROM
          (
            SELECT
              vl.mlsnum AS mlsnum,
              places.category as category,
              array_agg(places.label) AS label
            FROM
              (select * from crmls.view_property WHERE ST_Within(__geo_geom, ST_SetSRID(''::geometry,4326))) vl
              JOIN (select * from crmls.places where area_id = 41) as places ON ST_Contains(ST_SETSRID(places.way, 4326), vl.__geo_geom) 
            GROUP BY mlsnum, category
          ) mls_places
        WHERE category = 'Neighborhood'
      )
    neigh_places ON neigh_places.mlsnum = vl.mlsnum
;
